def read_groups():
    """Return {flour_type: [acidity_ml, ...]} from the titration sheet."""
    groups = {}
    with INPUT_PATH.open(newline="", encoding="ascii") as handle:
        for row in csv.DictReader(handle):
            groups.setdefault(row["flour_type"], []).append(float(row["acidity_ml"]))
    return groups
